import React, { useState, useCallback } from 'react';
import styled from '@emotion/styled';
import { Layout, NavTree, theme } from '@atlantis/shared';
import type { NavEntry } from '@atlantis/shared';
import PackageRadar from './components/PackageRadar';
import CommunityFeed from './components/CommunityFeed';
import DevPulse from './components/DevPulse';
import TechArticles from './components/TechArticles';

const SECTIONS: NavEntry[] = [
  {
    id: 'dashboard',
    name: 'Dashboard',
    icon: 'layout-grid',
    children: [
      { id: 'package-radar', name: 'Package Radar', icon: 'package' },
      { id: 'community-feed', name: 'Community Feed', icon: 'users' },
      { id: 'dev-pulse', name: 'Dev Pulse', icon: 'activity' },
      { id: 'tech-articles', name: 'Tech Articles', icon: 'book-open' },
    ],
  },
];

const Content = styled.div`
  padding: ${theme.spacing.xl};
  display: flex;
  flex-direction: column;
  gap: ${theme.spacing.xl};
  max-width: 1400px;
  width: 100%;
`;

const Section = styled.section`
  scroll-margin-top: ${theme.spacing.lg};
`;

const MidRow = styled.div`
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: ${theme.spacing.xl};

  @media (max-width: ${theme.breakpoints.lg}) {
    grid-template-columns: 1fr;
  }
`;

const Panel = styled.div`
  background: ${theme.colors.surface};
  border: 1px solid ${theme.colors.border};
  border-radius: ${theme.borderRadius.lg};
  padding: ${theme.spacing.lg};
`;

interface AppProps {
  topBarRight?: React.ReactNode;
}

export default function App({ topBarRight }: AppProps) {
  const [activeSection, setActiveSection] = useState<string | null>(null);

  const handleSelect = useCallback((entry: NavEntry) => {
    setActiveSection(entry.id);
    document.getElementById(entry.id)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }, []);

  const sidebar = (
    <NavTree entries={SECTIONS} activeId={activeSection} onSelect={handleSelect} />
  );

  return (
    <Layout title="DevHub" sidebar={sidebar} activeId={activeSection} topBarRight={topBarRight}>
      <Content>
        <Section id="package-radar">
          <Panel>
            <PackageRadar />
          </Panel>
        </Section>

        <MidRow>
          <Section id="community-feed">
            <Panel style={{ height: '100%' }}>
              <CommunityFeed />
            </Panel>
          </Section>
          <Section id="dev-pulse">
            <Panel style={{ height: '100%' }}>
              <DevPulse />
            </Panel>
          </Section>
        </MidRow>

        <Section id="tech-articles">
          <Panel>
            <TechArticles />
          </Panel>
        </Section>
      </Content>
    </Layout>
  );
}
